const n = (cells, [x,y]) => cells.filter(([a,b]) => !(a===x&&b===y) && Math.abs(a-x)<=1 && Math.abs(b-y)<=1).length;
const step = (cells) => {
  const key = c => c.join(",");
  const set = new Set(cells.map(key));
  const cand = new Map();
  for (const [x,y] of cells) for (let dx=-1;dx<=1;dx++) for (let dy=-1;dy<=1;dy++) cand.set(key([x+dx,y+dy]),[x+dx,y+dy]);
  const out=[];
  for (const [k,c] of cand) { const cnt=n(cells,c); if (set.has(k) ? (cnt===2||cnt===3) : cnt===3) out.push(c); }
  return out.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);
};
const show = (label, cells) => console.log(label, JSON.stringify(step(cells)));

console.log("R1 two adjacent:", "neighbours of (0,1)=", n([[0,1],[1,1]],[0,1]));
show("R1 [[0,1],[1,1]] ->", [[0,1],[1,1]]);

const r2 = [[0,0],[1,0],[2,0],[1,2]];
console.log("R2 centre (1,1) neighbours =", n(r2,[1,1]));

const r3 = [[0,0],[1,0],[2,0],[1,1],[0,2],[1,2],[2,2]];
console.log("R3 diagram centre (1,1) neighbours =", n(r3,[1,1]));

const r4 = [[0,0],[1,0],[0,1]];
console.log("R4 dead (1,1) neighbours =", n(r4,[1,1]));
show("R4 [[0,0],[1,0],[0,1]] ->", r4);

const bl0=[[0,0],[0,1],[0,2]];
show("Blinker gen0 ->", bl0);
show("Blinker gen1 ->", step(bl0));

show("Block ->", [[0,0],[1,0],[0,1],[1,1]]);
show("Single ->", [[0,0]]);
show("Empty ->", []);
show("Negative blinker [[-1,-1],[-1,0],[-1,1]] ->", [[-1,-1],[-1,0],[-1,1]]);
EOF
node /tmp/check.mjs

