  for (const cell of cells) {
    // A lone cell is nobody's neighbour, so it must seed itself.
    candidates.set(keyOf(cell), cell);
    for (const neighbour of neighboursOf(cell)) {
      candidates.set(keyOf(neighbour), neighbour);
    }
  }

