    13	
    14	const MIN_NEIGHBOURS_TO_SURVIVE = 2;
    15	const MAX_NEIGHBOURS_TO_SURVIVE = 3;
    16	const NEIGHBOURS_TO_REPRODUCE = 3;
    17	
    18	const isAliveNextGeneration = (
    19	  isAliveNow: boolean,
    20	  liveNeighbours: number
    21	): boolean => {
    22	  if (liveNeighbours < MIN_NEIGHBOURS_TO_SURVIVE) return false; // underpopulation
    23	  if (liveNeighbours > MAX_NEIGHBOURS_TO_SURVIVE) return false; // overpopulation
    24	  // Within the survival range from here on.
    25	  if (isAliveNow) return true; // survival
    26	  return liveNeighbours === NEIGHBOURS_TO_REPRODUCE; // reproduction
    27	};
    28	
    29	export const nextGeneration = (cells: Cell[]): Cell[] => {
    30	  const liveKeys = new Set(cells.map(keyOf));
    31	  const isAlive = (cell: Cell): boolean => liveKeys.has(keyOf(cell));
    32	  const countLiveNeighbours = (cell: Cell): number =>
